effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 g = c * pow(2.0, exposure);
  g = clamp((g - 0.5) * contrast + 0.5, 0.0, 1.0);
  g = pow(g, vec3(1.0 / max(gamma, 0.05)));
  g = g * gain;
  g = lift + g * (1.0 - lift);
  vec3 col = mix(c, clamp(g, 0.0, 1.0), mixAmt);
  gl_FragColor = vec4(col * a, a);
}
